/*
 * A380725  Positive integers k whose sum of digits equals the square of their
 *          number of digits.
 * https://oeis.org/A380725
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, fini, full, easy
 * Formula:   This function returns the nth element of OEIS A380725, * namely
 *            the positive integers k whose sum of digits equals the square *
 *            of the number of digits. The sequence is generated by
 *            enumerating * all numbers with 1 to 9 digits that satisfy the
 *            required digit sum
 * Range:     u8 n <= 20, u16 n <= 3617, u32 n <= 8917, u64 n <= 8917,
 *            u128 n <= 8917, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>

/* Preallocate storage for all terms – the sequence has fewer than
 * 100 000 elements, so 200 000 provides ample safety margin. */
static seq_t seq[200000];
static size_t seq_length = 0;

/* Recursively build numbers of a given length that have the required
 * digit sum (rem).  cur holds the value of the digits processed so far. */
static void generate_recursive(int len, int pos, int rem, seq_t cur)
{
    if (pos == len) {
        if (rem == 0)
            seq[seq_length++] = cur;
        return;
    }

    int remaining_positions = len - pos - 1;
    int max_possible = 9 * remaining_positions;
    for (int d = (pos == 0 ? 1 : 0); d <= 9; ++d) {
        int new_rem = rem - d;
        if (new_rem < 0)
            break;                /* larger d will only increase the difference */
        if (new_rem > max_possible)
            continue;             /* too many digits remaining would be required */
        seq_t new_cur = cur * 10 + (seq_t)d;
        generate_recursive(len, pos + 1, new_rem, new_cur);
    }
}

/* Generate the entire sequence once, in ascending order. */
static void generate_all(void)
{
    for (int len = 1; len <= 9; ++len) {
        generate_recursive(len, 0, len * len, 0);
    }
}

seq_t a(idx_t n)
{
    if (seq_length == 0)
        generate_all();

    if (n == 0 || (idx_t)(n - 1) >= seq_length)
        return 0;      /* out of bounds – sequence is finite */

    return seq[n - 1];
}
